            assign s_valid[i] = s_axis_tvalid[i];
            assign s_last[i] = s_axis_tlast[i];
            assign s_dest[i*S_DEST_WIDTH +: S_DEST_WIDTH] = s_axis_tdest[i*S_DEST_WIDTH +: S_DEST_WIDTH];
